interface CuratedSeed {
  readonly id: string
  readonly title: string
  readonly stars: string
  readonly outcome: string
  readonly summary: string
  readonly industryIds: readonly IndustryId[]
  readonly kindIds: readonly AbilityKindId[]
  readonly developerDirectionIds?: readonly DeveloperDirectionId[]
  readonly extensionTypes: readonly ExtensionType[]
  readonly compatibility: CompatibilityPath
  readonly trust: TrustTier
  readonly repositoryUrl: string
  readonly source: string
  readonly aliases?: readonly string[]
  readonly examples?: readonly string[]
  readonly checks?: readonly string[]
}

const BASE_CHECKS = ['先阅读官方 README 并固定版本', '密钥与生产权限默认不授予', '完成后提供验证、停用和卸载方法']
const RESEARCH_CHECKS = ['保留来源、日期和引用链接', '区分原文事实、工具输出和 AI 推断', '论文与统计结论必须人工复核']
const FINANCE_CHECKS = ['只用于研究和开发，不提供自动交易权限', '标明数据来源、时间与可能的延迟', '任何资金、下单或账户写操作保持关闭']

function addMethod(seed: CuratedSeed): string {
  if (seed.compatibility === 'skill-copy') {
    return '打开仓库并只选择与当前任务相关的 Skill；先让创造模式核对目录、依赖和提示词，再复制到用户自己的 Skill 目录中验证。'
  }
  if (seed.compatibility === 'mcp') {
    return '按仓库 README 在 Harness 中建立 MCP Client 配置；先使用只读或测试账户验证工具清单、环境变量、超时和停止方式。'
  }
  return '把它作为独立项目级工具运行，先完成最小示例；确有长期价值时，再通过创造模式封装成 Skill、Workflow、MCP 或受限插件。'
}

function curatedAbility(seed: CuratedSeed): AbilityDefinition {
  return {
    id: seed.id,
    title: seed.title,
    outcome: seed.outcome,
    summary: seed.summary,
    industryIds: seed.industryIds,
    kindIds: seed.kindIds,
    developerDirectionIds: seed.developerDirectionIds ?? [],
    collectionIds: [],
    aliases: seed.aliases ?? [seed.title, seed.outcome],
    examples: seed.examples ?? [seed.outcome],
    userProvides: '你的目标、项目或资料位置，以及允许访问的数据和服务范围。',
    userReceives: '一个可验证、可停用，并能按需接入 DeepSeek Harness 的能力方案。',
    suitableFor: '你希望使用成熟开源项目增强 Harness，而不是从零重复开发。',
    readsOrChanges: '只读取你明确指定的项目、资料或测试服务；远程写操作需要单独确认。',
    rollback: '删除对应 Skill 或 MCP 配置，或停止独立工具并按变更清单回退。',
    estimatedTime: seed.compatibility === 'project-tool' ? '约 20–60 分钟' : '约 10–30 分钟',
    ecosystem: 'vendor',
    trust: seed.trust,
    compatibility: seed.compatibility,
    popularity: `GitHub 约 ${seed.stars} 星；2026-08-17 快照`,
    implementation: {
      extensionTypes: seed.extensionTypes,
      goal: `请先评估 ${seed.title} 是否适合我的目标，说明它能解决什么、需要什么权限，以及最小接入方案；未经确认不要安装或写入远程服务。`,
      addMethod: addMethod(seed),
      checks: seed.checks ?? BASE_CHECKS,
      source: seed.source,
      license: '以仓库当前声明为准',
      repositoryUrl: seed.repositoryUrl,
    },
  }
}

