import type {
  AbilityDefinition,
  AbilityKindId,
  CompatibilityPath,
  EcosystemId,
  ExtensionType,
  IndustryId,
  TrustTier,
} from './catalog.ts'
import {
  DEVELOPER_DIRECTIONS_BY_ABILITY_ID,
  type DeveloperDirectionId,
} from './developer-directions.ts'

type CatalogSeed = Omit<AbilityDefinition, 'developerDirectionIds' | 'userProvides' | 'userReceives' | 'suitableFor' | 'readsOrChanges' | 'rollback' | 'estimatedTime' | 'implementation'> & {
  readonly developerDirectionIds?: readonly DeveloperDirectionId[]
  readonly userProvides?: string
  readonly userReceives?: string
  readonly suitableFor?: string
  readonly readsOrChanges?: string
  readonly rollback?: string
  readonly estimatedTime?: string
  readonly implementation: AbilityDefinition['implementation']
  readonly ecosystem: EcosystemId
  readonly trust: TrustTier
  readonly compatibility: CompatibilityPath
  readonly popularity: string
}

function repoAbility(seed: CatalogSeed): AbilityDefinition {
  return {
    ...seed,
    developerDirectionIds: seed.developerDirectionIds ?? DEVELOPER_DIRECTIONS_BY_ABILITY_ID[seed.id] ?? [],
    userProvides: seed.userProvides ?? '你的目标、项目位置和希望 AI 完成的具体任务。',
    userReceives: seed.userReceives ?? '一套可以按步骤添加、验证和关闭的能力。',
    suitableFor: seed.suitableFor ?? '你想让 DeepSeek Harness 多做一类明确的工作。',
    readsOrChanges: seed.readsOrChanges ?? '只读取你指定的项目或公开来源；远程写操作需要你单独确认。',
    rollback: seed.rollback ?? '停用对应 Skill、删除 MCP 配置或按项目变更清单回退。',
    estimatedTime: seed.estimatedTime ?? '约 5–20 分钟',
  }
}

interface ShortCatalogSeed {
  readonly id: string
  readonly title: string
  readonly outcome: string
  readonly summary: string
  readonly industryIds: readonly IndustryId[]
  readonly kindIds: readonly AbilityKindId[]
  readonly aliases: readonly string[]
  readonly examples: readonly string[]
  readonly ecosystem: EcosystemId
  readonly trust: TrustTier
  readonly compatibility: CompatibilityPath
  readonly popularity: string
  readonly extensionTypes: readonly ExtensionType[]
  readonly goal: string
  readonly addMethod: string
  readonly checks: readonly string[]
  readonly source: string
  readonly license: string
  readonly repositoryUrl: string
}

function shortAbility(seed: ShortCatalogSeed): AbilityDefinition {
  return repoAbility({
    id: seed.id,
    title: seed.title,
    outcome: seed.outcome,
    summary: seed.summary,
    industryIds: seed.industryIds,
    kindIds: seed.kindIds,
    collectionIds: [],
    aliases: seed.aliases,
    examples: seed.examples,
    ecosystem: seed.ecosystem,
    trust: seed.trust,
    compatibility: seed.compatibility,
    popularity: seed.popularity,
    implementation: {
      extensionTypes: seed.extensionTypes,
      goal: seed.goal,
      addMethod: seed.addMethod,
      checks: seed.checks,
      source: seed.source,
      license: seed.license,
      repositoryUrl: seed.repositoryUrl,
    },
  })
}

